// Ambient bakery soundscape, generated live with the Web Audio API (no audio files):
//   - music:  a bright, bouncy bakery-café loop (104 BPM, C - G - Am - F) - off-beat
//             chord stabs, a jumping bass line, a soft café drum kit, and a skipping
//             music-box melody that's re-composed every bar (so it never repeats exactly)
//   - bakery: a low oven/room hum, a soft warm crackle, distant clinks of trays and
//             utensils at random moments, and the occasional soft oven-timer ding
// Usage: startAmbience() / stopAmbience() (both safe to call repeatedly). Follows the
// game's mute button. Where it plays is configured in src/config/ambience.js.
import { isMuted, onMuteChange } from './sounds';
import { AMBIENCE } from './config/ambience';

const BPM = 104;
const BEAT = 60 / BPM;
const BAR = BEAT * 4;
const EIGHTH = BEAT / 2;
const SIXTEENTH = BEAT / 4;

// A bright, happy C -> G -> Am -> F, one bar each (MIDI note numbers)
const CHORDS = [
  { root: 36, tones: [52, 55, 60, 64] },
  { root: 43, tones: [50, 55, 59, 62] },
  { root: 45, tones: [52, 57, 60, 64] },
  { root: 41, tones: [53, 57, 60, 65] },
];
// Melody notes: C major pentatonic, C5 - E6
const MELODY_SCALE = [72, 74, 76, 79, 81, 84, 86, 88];
// Which 16th-notes of the bar the melody plays on - one picked at random per bar.
// Busy and syncopated, so the melody skips along rather than drifting.
const RHYTHMS = [
  [0, 2, 4, 6, 8, 11, 12, 14],
  [0, 3, 6, 8, 10, 12, 14],
  [2, 4, 7, 8, 10, 13, 14],
  [0, 2, 3, 6, 8, 10, 11, 14],
  [0, 4, 6, 7, 8, 12, 14, 15],
  [0, 1, 2, 4, 8, 10, 12],
];
// Bouncy bass: which 8th-notes it plays on, and how far above the chord root (semitones)
const BASS_LINE = [[0, 0], [2, 12], [3, 0], [4, 7], [6, 12], [7, 7]];
// Off-beat chord stabs (8th-notes), like a café piano
const STABS = [1, 3, 4, 6];

const mtof = (m) => 440 * Math.pow(2, (m - 69) / 12);
const rand = (min, max) => min + Math.random() * (max - min);

let ctx = null;
let master, musicBus, bakeryBus, padFilter, delaySend;
let noiseBuffer = null;
let bedStarted = false;
let playing = false;
let scheduling = false;
let barTimer = null, clinkTimer = null, dingTimer = null, stopTimer = null;
let nextBarTime = 0;
let barIndex = 0;
let melodyStep = 3;

function targetLevel() {
  return isMuted() ? 0 : AMBIENCE.masterVolume;
}

function fadeTo(value, seconds) {
  const t = ctx.currentTime;
  master.gain.cancelScheduledValues(t);
  master.gain.setValueAtTime(master.gain.value, t);
  master.gain.linearRampToValueAtTime(value, t + seconds);
}

function makeNoise(seconds, fill) {
  const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
  fill(buffer.getChannelData(0));
  return buffer;
}

function ensureContext() {
  if (ctx) return;
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return;
  ctx = new AudioCtx();

  master = ctx.createGain();
  master.gain.value = 0;
  master.connect(ctx.destination);

  musicBus = ctx.createGain();
  musicBus.gain.value = AMBIENCE.musicVolume;
  musicBus.connect(master);

  bakeryBus = ctx.createGain();
  bakeryBus.gain.value = AMBIENCE.bakeryVolume;
  bakeryBus.connect(master);

  // Pads + chord stabs: warm but bright enough to feel awake
  padFilter = ctx.createBiquadFilter();
  padFilter.type = 'lowpass';
  padFilter.frequency.value = 2200;
  padFilter.Q.value = 0.5;
  padFilter.connect(musicBus);

  // Dotted-eighth echo on the music-box melody - shorter tail so it stays crisp
  delaySend = ctx.createGain();
  delaySend.gain.value = 0.28;
  const delay = ctx.createDelay(2);
  delay.delayTime.value = BEAT * 0.75;
  const feedback = ctx.createGain();
  feedback.gain.value = 0.24;
  const echoTone = ctx.createBiquadFilter();
  echoTone.type = 'lowpass';
  echoTone.frequency.value = 2800;
  delaySend.connect(delay);
  delay.connect(echoTone);
  echoTone.connect(feedback);
  feedback.connect(delay);
  echoTone.connect(musicBus);

  noiseBuffer = makeNoise(1, (d) => { for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; });

  // Browsers only allow audio after the player has interacted with the page - if it
  // starts out suspended, wake it up on the first click / key / touch.
  const unlock = () => {
    ctx.resume().then(() => { if (playing) beginScheduling(); });
    ['pointerdown', 'keydown', 'touchstart'].forEach(e => window.removeEventListener(e, unlock));
  };
  if (ctx.state !== 'running') {
    ['pointerdown', 'keydown', 'touchstart'].forEach(e => window.addEventListener(e, unlock));
  }

  onMuteChange(() => { if (playing) fadeTo(targetLevel(), 0.4); });
}

/* ---------------- Music ---------------- */

// Soft sustained chord underneath everything (quieter now - the stabs carry the rhythm)
function pad(midi, start, dur) {
  const f = mtof(midi);
  [-5, 5].forEach(detune => {
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = f;
    osc.detune.value = detune;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, start);
    g.gain.linearRampToValueAtTime(0.011, start + 0.3);
    g.gain.setValueAtTime(0.011, start + dur - 0.1);
    g.gain.linearRampToValueAtTime(0, start + dur + 0.4);
    osc.connect(g);
    g.connect(padFilter);
    osc.start(start);
    osc.stop(start + dur + 0.5);
  });
}

// Short, plucky chord hit on the off-beat - the café-piano bounce
function stab(tones, start, velocity) {
  tones.forEach(midi => {
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = mtof(midi + 12);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, start);
    g.gain.linearRampToValueAtTime(0.02 * velocity, start + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0006, start + 0.22);
    osc.connect(g);
    g.connect(padFilter);
    osc.start(start);
    osc.stop(start + 0.25);
  });
}

// Bouncy bass note: round sine with a touch of triangle for definition, short decay
function bass(midi, start, velocity = 1) {
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, start);
  g.gain.linearRampToValueAtTime(0.08 * velocity, start + 0.012);
  g.gain.exponentialRampToValueAtTime(0.001, start + EIGHTH * 1.6);
  g.connect(musicBus);
  [['sine', 1], ['triangle', 0.35]].forEach(([type, level]) => {
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = mtof(midi);
    const lg = ctx.createGain();
    lg.gain.value = level;
    osc.connect(lg);
    lg.connect(g);
    osc.start(start);
    osc.stop(start + EIGHTH * 1.7);
  });
}

// Music-box pluck: a bell-ish blend of partials, crisp attack, shorter ring than before
function pluck(midi, start, velocity) {
  const f = mtof(midi);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, start);
  g.gain.linearRampToValueAtTime(0.05 * velocity, start + 0.005);
  g.gain.exponentialRampToValueAtTime(0.0008, start + 0.9);
  g.connect(musicBus);
  g.connect(delaySend);
  [[1, 1], [2, 0.32], [3.01, 0.12]].forEach(([ratio, level]) => {
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = f * ratio;
    const pg = ctx.createGain();
    pg.gain.value = level;
    osc.connect(pg);
    pg.connect(g);
    osc.start(start);
    osc.stop(start + 1);
  });
}

/* Soft café drum kit - light enough to stay cosy, but it gives the loop a pulse */

function kick(start) {
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(130, start);
  osc.frequency.exponentialRampToValueAtTime(45, start + 0.12);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, start);
  g.gain.linearRampToValueAtTime(0.16, start + 0.005);
  g.gain.exponentialRampToValueAtTime(0.001, start + 0.3);
  osc.connect(g);
  g.connect(musicBus);
  osc.start(start);
  osc.stop(start + 0.32);
}

function clap(start) {
  // noisy snap + a little tonal body
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.frequency.value = 1900;
  bp.Q.value = 0.8;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, start);
  g.gain.linearRampToValueAtTime(0.07, start + 0.004);
  g.gain.exponentialRampToValueAtTime(0.001, start + 0.16);
  src.connect(bp);
  bp.connect(g);
  g.connect(musicBus);
  src.start(start, Math.random() * 0.7, 0.2);

  const body = ctx.createOscillator();
  body.type = 'triangle';
  body.frequency.value = 190;
  const bg = ctx.createGain();
  bg.gain.setValueAtTime(0, start);
  bg.gain.linearRampToValueAtTime(0.03, start + 0.004);
  bg.gain.exponentialRampToValueAtTime(0.001, start + 0.1);
  body.connect(bg);
  bg.connect(musicBus);
  body.start(start);
  body.stop(start + 0.12);
}

function hat(start, level) {
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  const hp = ctx.createBiquadFilter();
  hp.type = 'highpass';
  hp.frequency.value = 7500;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, start);
  g.gain.linearRampToValueAtTime(level, start + 0.003);
  g.gain.exponentialRampToValueAtTime(0.0004, start + 0.05);
  src.connect(hp);
  hp.connect(g);
  g.connect(musicBus);
  src.start(start, Math.random() * 0.8, 0.08);
}

function scheduleBar() {
  if (!playing || !scheduling) return;
  if (nextBarTime < ctx.currentTime + 0.05) nextBarTime = ctx.currentTime + 0.1; // e.g. after a background tab

  const t = nextBarTime;
  const chord = CHORDS[barIndex % CHORDS.length];

  // Harmony: a quiet bed + bouncy off-beat stabs
  chord.tones.forEach(m => pad(m, t, BAR));
  STABS.forEach(slot => stab(chord.tones, t + slot * EIGHTH, slot % 2 ? 1 : 0.75));

  // Bass jumping between the root, its octave and its fifth
  BASS_LINE.forEach(([slot, offset]) => bass(chord.root + offset, t + slot * EIGHTH, slot === 0 ? 1 : 0.8));

  // Drums: kick on 1 and 3 (plus a pickup into every 4th bar), clap on 2 and 4,
  // hats ticking on every 8th with the off-beats a little louder
  kick(t);
  kick(t + 2 * BEAT);
  if (barIndex % 4 === 3) kick(t + 3.5 * BEAT);
  clap(t + BEAT);
  clap(t + 3 * BEAT);
  for (let i = 0; i < 8; i++) hat(t + i * EIGHTH, i % 2 ? 0.022 : 0.012);

  // A new little melody every bar, skipping step-wise through the scale; the first
  // note of each beat gets a slight accent
  const rhythm = RHYTHMS[Math.floor(Math.random() * RHYTHMS.length)];
  rhythm.forEach(slot => {
    melodyStep = Math.max(0, Math.min(MELODY_SCALE.length - 1, melodyStep + [-2, -1, -1, 0, 1, 1, 2][Math.floor(Math.random() * 7)]));
    pluck(MELODY_SCALE[melodyStep], t + slot * SIXTEENTH + rand(0, 0.008), (slot % 4 === 0 ? 1 : 0.7) * rand(0.85, 1));
  });

  barIndex += 1;
  nextBarTime += BAR;
  barTimer = setTimeout(scheduleBar, Math.max(50, (nextBarTime - ctx.currentTime - 0.6) * 1000));
}

/* ---------------- Bakery sounds ---------------- */

function startBed() {
  if (bedStarted) return;
  bedStarted = true;

  // Low oven / room hum: brown noise through a gently wavering low-pass
  const brown = makeNoise(4, (d) => {
    let last = 0;
    for (let i = 0; i < d.length; i++) {
      last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      d[i] = last * 3.5;
    }
  });
  const hum = ctx.createBufferSource();
  hum.buffer = brown;
  hum.loop = true;
  const humFilter = ctx.createBiquadFilter();
  humFilter.type = 'lowpass';
  humFilter.frequency.value = 260;
  const lfo = ctx.createOscillator();
  lfo.frequency.value = 0.07;
  const lfoDepth = ctx.createGain();
  lfoDepth.gain.value = 80;
  lfo.connect(lfoDepth);
  lfoDepth.connect(humFilter.frequency);
  const humGain = ctx.createGain();
  humGain.gain.value = 0.07;
  hum.connect(humFilter);
  humFilter.connect(humGain);
  humGain.connect(bakeryBus);
  hum.start();
  lfo.start();

  // Soft, warm crackle (like a cosy old radio in the corner)
  const crackle = makeNoise(3, (d) => {
    for (let i = 0; i < d.length; i++) {
      if (Math.random() < 22 / ctx.sampleRate) {
        const amp = rand(0.2, 0.7) * (Math.random() < 0.5 ? -1 : 1);
        for (let k = 0; k < 40 && i + k < d.length; k++) d[i + k] += amp * Math.exp(-k / 6);
      }
    }
  });
  const crackleSrc = ctx.createBufferSource();
  crackleSrc.buffer = crackle;
  crackleSrc.loop = true;
  const crackleTone = ctx.createBiquadFilter();
  crackleTone.type = 'bandpass';
  crackleTone.frequency.value = 2500;
  crackleTone.Q.value = 0.7;
  const crackleGain = ctx.createGain();
  crackleGain.gain.value = 0.05;
  crackleSrc.connect(crackleTone);
  crackleTone.connect(crackleGain);
  crackleGain.connect(bakeryBus);
  crackleSrc.start();
}

// A distant metallic clink - trays, whisks, a spoon on a bowl
function clink(start) {
  const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
  const out = ctx.createGain();
  out.gain.value = 1;
  if (pan) { pan.pan.value = rand(-0.8, 0.8); out.connect(pan); pan.connect(bakeryBus); } else { out.connect(bakeryBus); }
  const base = rand(0.88, 1.12);
  [[2093, 0.012, 0.7], [3136, 0.008, 0.5], [4400, 0.005, 0.35]].forEach(([freq, level, decay]) => {
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = freq * base;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, start);
    g.gain.linearRampToValueAtTime(level, start + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0002, start + decay);
    osc.connect(g);
    g.connect(out);
    osc.start(start);
    osc.stop(start + decay + 0.05);
  });
}

// Soft two-note oven-timer ding
function ding(start) {
  [[1318.5, 0], [1046.5, 0.38]].forEach(([freq, offset]) => {
    [[1, 0.02], [2.76, 0.004]].forEach(([ratio, level]) => {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq * ratio;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, start + offset);
      g.gain.linearRampToValueAtTime(level, start + offset + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0002, start + offset + 2.2);
      osc.connect(g);
      g.connect(bakeryBus);
      osc.start(start + offset);
      osc.stop(start + offset + 2.3);
    });
  });
}

function scheduleClinks() {
  clinkTimer = setTimeout(() => {
    if (!playing) return;
    const t = ctx.currentTime + 0.05;
    clink(t);
    if (Math.random() < 0.35) clink(t + rand(0.12, 0.3)); // sometimes a little double clink
    scheduleClinks();
  }, rand(2500, 7000));
}

function scheduleDings() {
  dingTimer = setTimeout(() => {
    if (!playing) return;
    ding(ctx.currentTime + 0.05);
    scheduleDings();
  }, rand(35000, 70000));
}

/* ---------------- Start / stop ---------------- */

function beginScheduling() {
  if (scheduling || !playing || ctx.state !== 'running') return;
  scheduling = true;
  startBed();
  nextBarTime = ctx.currentTime + 0.2;
  scheduleBar();
  scheduleClinks();
  scheduleDings();
  fadeTo(targetLevel(), 3);
}

export function startAmbience() {
  ensureContext();
  if (!ctx) return;
  clearTimeout(stopTimer);
  if (playing) return;
  playing = true;
  if (ctx.state === 'running') beginScheduling();
  else ctx.resume().then(() => { if (playing) beginScheduling(); }).catch(() => { /* waits for a gesture */ });
}

export function stopAmbience() {
  if (!ctx || !playing) return;
  playing = false;
  scheduling = false;
  clearTimeout(barTimer);
  clearTimeout(clinkTimer);
  clearTimeout(dingTimer);
  fadeTo(0, 1.5);
  // Once faded out, pause the audio engine entirely (so the hum/crackle stop costing
  // anything); startAmbience() resumes it.
  stopTimer = setTimeout(() => { if (!playing) ctx.suspend(); }, 1700);
}
